def draw_bird(x, y):
    draw_image("images/bird.png", x, y)


def draw_pipe(x, gap_y):
    draw_image("images/pipe.png", x, gap_y - 440, flip=True)
    draw_image("images/pipe.png", x, gap_y + GAP)


GAP = 150
pipe_x = 400
pipe_gap = 220
game_over = False
score = 0
scored = False


class Bird:
    def __init__(self):
        self.y = 300
        self.speed = 0

    def update(self):
        if key_pressed():
            self.speed = -8
        self.speed = self.speed + 0.5
        self.y = self.y + self.speed
        if self.y > 480:
            self.y = 480
            self.speed = 0

    def draw(self):
        draw_bird(100, self.y)


bird = Bird()


def hits():
    if 100 + 44 - 8 < pipe_x or 100 + 8 > pipe_x + 52:
        return False
    return bird.y + 8 < pipe_gap or bird.y + 40 - 8 > pipe_gap + GAP


def update():
    global pipe_x, game_over, score, scored
    if game_over:
        return
    bird.update()
    pipe_x = pipe_x - 2
    if pipe_x + 52 < 100 and not scored:
        score = score + 1
        scored = True
    if hits():
        game_over = True


def draw():
    clear("skyblue")
    draw_pipe(pipe_x - 12, pipe_gap)
    bird.draw()
    draw_text(str(score), 200, 60, 56)
    if game_over:
        draw_text("Thua rồi!", 200, 250, 48)

