from pyquest import *

from bird import Bird


def draw_pipe(x, gap_y):
    draw_image("images/pipe.png", x, gap_y - 440, flip=True)
    draw_image("images/pipe.png", x, gap_y + GAP)


GAP = 150
pipe_x = 400
pipe_gap = 220
state = "ready"
score = 0
scored = False


bird = Bird()


def hits():
    if 100 + 44 - 8 < pipe_x or 100 + 8 > pipe_x + 52:
        return False
    return bird.y + 8 < pipe_gap or bird.y + 40 - 8 > pipe_gap + GAP


def update():
    global pipe_x, state, score, scored
    if state == "ready":
        if not key_pressed():
            return
        state = "play"
    if state == "over":
        return
    bird.update()
    pipe_x = pipe_x - 2
    if pipe_x + 52 < 100 and not scored:
        score = score + 1
        scored = True
    if hits():
        state = "over"


def draw():
    clear("skyblue")
    draw_pipe(pipe_x - 12, pipe_gap)
    bird.draw()
    draw_text(str(score), 200, 60, 56)
    if state == "ready":
        draw_text("Bấm Space để bay", 200, 400, 32)
    if state == "over":
        draw_text("Thua rồi!", 200, 250, 48)

